# =============================================================================
# 공공데이터포털(data.go.kr) 인증키 안전 로드 & 실시간 API 호출 엔진
# =============================================================================

def resolve_api_key() -> tuple[str, str]:
    """
    우선순위:
    1) 앱 내 사용자가 직접 입력한 세션 키
    2) Streamlit Secrets (DATA_GO_KR_API_KEY / OPEN_DATA_KEY / SERVICE_KEY / api_key)
    3) 운영체제 환경변수 (DATA_GO_KR_API_KEY / OPEN_DATA_KEY / SERVICE_KEY)
    ※ GitHub 공개 저장소에 키가 노출되지 않도록 코드 내부에 실제 키 문자열을 하드코딩하지 않습니다.
    """
    manual_key = st.session_state.get("manual_api_key", "").strip()
    if manual_key:
        return manual_key, "화면 직접 입력"

    secret_candidates = (
        "DATA_GO_KR_API_KEY",
        "OPEN_DATA_KEY",
        "DATA_GOK_KEY",
        "SERVICE_KEY",
        "open_data_key",
        "api_key",
    )
    try:
        for k in secret_candidates:
            if k in st.secrets and str(st.secrets[k]).strip():
                return str(st.secrets[k]).strip(), f"Streamlit Secrets ({k})"
    except Exception:
        pass

    for k in secret_candidates:
        val = os.environ.get(k, "").strip()
        if val:
            return val, f"환경변수 ({k})"

    return "", "미설정"


def _normalize_service_key(raw_key: str) -> str:
    """Decoding 키든 Encoding(%포함) 키든 URL 쿼리에 안전하게 들어가도록 정규화"""
    k = raw_key.strip()
    if "%" in k:
        return k
    return urllib.parse.quote(k, safe="")


def _http_get_text(url: str, timeout: float = 5.0) -> tuple[int, str]:
    ctx = ssl.create_default_context()
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (GeumsanBusApp/2.0)"})
    try:
        with urllib.request.urlopen(req, timeout=timeout, context=ctx) as resp:
            return resp.status, resp.read().decode("utf-8", errors="replace")
    except urllib.error.HTTPError as he:
        body = he.read().decode("utf-8", errors="replace") if he.fp else ""
        return he.code, body
    except Exception as exc:
        return 0, str(exc)


def _extract_tago_items(payload: dict) -> list[dict]:
    body = payload.get("response", {}).get("body", {})
    if not isinstance(body, dict):
        return []
    items = body.get("items", "")
    if not items or not isinstance(items, dict):
        return []
    item = items.get("item", [])
    if isinstance(item, dict):
        return [item]
    if isinstance(item, list):
        return item
    return []


@st.cache_data(ttl=20, show_spinner=False)
def fetch_tago_bus_locations(service_key: str, city_code: int, route_id: str) -> dict:
    """
    국토교통부(TAGO) 버스위치정보 API (BusLcInfoInqireService/getRouteAcctoBusLcList)
    - 현재 노선 위를 달리고 있는 모든 차량의 실시간 정류장 위치(nodenm, nodeord, vehicleno) 조회
    """
    if not service_key:
        return {"ok": False, "auth_err": False, "buses": [], "msg": "API 키 미설정"}

    enc_key = _normalize_service_key(service_key)
    url = (
        f"https://apis.data.go.kr/1613000/BusLcInfoInqireService/getRouteAcctoBusLcList"
        f"?serviceKey={enc_key}&cityCode={city_code}&routeId={urllib.parse.quote(route_id)}"
        f"&numOfRows=50&pageNo=1&_type=json"
    )
    status, text = _http_get_text(url, timeout=5.0)
    if status == 403 or "SERVICE_KEY_IS_NOT_REGISTERED" in text or " Pertinent" in text:
        return {"ok": False, "auth_err": True, "buses": [], "msg": "버스위치정보 API 활용신청 미등록 또는 승인 대기"}
    if status != 200:
        return {"ok": False, "auth_err": False, "buses": [], "msg": f"통신 지연 (HTTP {status})"}

    try:
        data = json.loads(text)
    except Exception:
        if "SERVICE_KEY" in text or "LIMITED" in text:
            return {"ok": False, "auth_err": True, "buses": [], "msg": "인증키 오류 또는 트래픽 한도 초과"}
        return {"ok": False, "auth_err": False, "buses": [], "msg": "응답 파싱 실패"}

    header = data.get("response", {}).get("header", {})
    if str(header.get("resultCode", "")) not in ("00", "0"):
        return {
            "ok": False,
            "auth_err": "KEY" in str(header.get("resultMsg", "")).upper(),
            "buses": [],
            "msg": str(header.get("resultMsg", "API 오류")),
        }

    raw_items = _extract_tago_items(data)
    buses = []
    for it in raw_items:
        try:
            ord_val = int(it.get("nodeord", 0))
        except Exception:
            ord_val = 0
        buses.append(
            {
                "node_id": str(it.get("nodeid", "")),
                "node_nm": str(it.get("nodenm", "")).strip(),
                "node_ord": ord_val,
                "route_nm": str(it.get("routenm", "")).strip(),
                "vehicle_no": str(it.get("vehicleno", "")).strip(),
                "lat": it.get("gpslati"),
                "lon": it.get("gpslong"),
            }
        )
    buses.sort(key=lambda b: b["node_ord"])
    return {"ok": True, "auth_err": False, "buses": buses, "msg": "정상"}


@st.cache_data(ttl=20, show_spinner=False)
def fetch_tago_stop_arrival(service_key: str, city_code: int, node_id: str, route_id: str = "") -> dict:
    """
    국토교통부(TAGO) 버스도착정보 API (ArvlInfoInqireService)
    - 정류소별 남은 도착 시간(arrtime 초) 및 남은 정거장 수(arrprevstationcnt) 조회
    - 사용자가 ArvlInfoInqireService 활용신청을 추가하면 자동으로 정확한 초 단위 예측까지 활성화됨
    """
    if not service_key or not node_id:
        return {"ok": False, "items": []}

    enc_key = _normalize_service_key(service_key)
    if route_id:
        url = (
            f"https://apis.data.go.kr/1613000/ArvlInfoInqireService/getSttnAcctoSpcifyRouteBusArvlPrearngeInfoList"
            f"?serviceKey={enc_key}&cityCode={city_code}&nodeId={urllib.parse.quote(node_id)}"
            f"&routeId={urllib.parse.quote(route_id)}&numOfRows=10&pageNo=1&_type=json"
        )
    else:
        url = (
            f"https://apis.data.go.kr/1613000/ArvlInfoInqireService/getSttnAcctoArvlPrearngeInfoList"
            f"?serviceKey={enc_key}&cityCode={city_code}&nodeId={urllib.parse.quote(node_id)}"
            f"&numOfRows=20&pageNo=1&_type=json"
        )
    status, text = _http_get_text(url, timeout=4.0)
    if status != 200:
        return {"ok": False, "items": []}
    try:
        data = json.loads(text)
    except Exception:
        return {"ok": False, "items": []}
    header = data.get("response", {}).get("header", {})
    if str(header.get("resultCode", "")) not in ("00", "0"):
        return {"ok": False, "items": []}

    parsed = []
    for it in _extract_tago_items(data):
        try:
            arr_sec = int(it.get("arrtime", 0))
            prev_cnt = int(it.get("arrprevstationcnt", 0))
        except Exception:
            continue
        parsed.append(
            {
                "route_no": str(it.get("routeno", "")).strip(),
                "route_id": str(it.get("routeid", "")).strip(),
                "arr_sec": arr_sec,
                "arr_min": max(1, round(arr_sec / 60)) if arr_sec > 30 else 0,
                "prev_cnt": prev_cnt,
            }
        )
    parsed.sort(key=lambda x: x["arr_sec"])
    return {"ok": True, "items": parsed}


@st.cache_data(ttl=20, show_spinner=False)
def fetch_daejeon_ars_arrival(service_key: str, ars_id: str, target_route_no: str = "34") -> dict:
    """
    대전광역시 정류소별 도착정보 API (apis.data.go.kr/6300000/arrive/getArrInfoByUid)
    - 5자리 정류장 번호(예: 74650 진산, 74450 복수면사무소, 22370 서남부터미널)로 전광판 정보 직접 조회
    """
    if not service_key or not ars_id or len(ars_id.strip()) < 4:
        return {"ok": False, "items": []}

    enc_key = _normalize_service_key(service_key)
    url = f"https://apis.data.go.kr/6300000/arrive/getArrInfoByUid?serviceKey={enc_key}&arsId={urllib.parse.quote(ars_id.strip())}"
    status, text = _http_get_text(url, timeout=4.0)
    if status != 200 or "<itemList>" not in text:
        return {"ok": False, "items": []}

    try:
        root = ET.fromstring(text)
    except Exception:
        return {"ok": False, "items": []}

    results = []
    for item in root.findall(".//itemList"):
        r_no = (item.findtext("ROUTE_NO") or "").strip()
        if target_route_no and r_no != target_route_no:
            continue
        ext_min_raw = (item.findtext("EXTIME_MIN") or "").strip()
        ext_sec_raw = (item.findtext("EXTIME_SEC") or "").strip()
        msg_tp = (item.findtext("MSG_TP") or "").strip()
        status_pos = (item.findtext("STATUS_POS") or "").strip()
        last_cat = (item.findtext("LAST_CAT") or "").strip()
        dest_nm = (item.findtext("DESTINATION") or "").strip()

        arr_min = None
        if ext_min_raw.isdigit():
            arr_min = int(ext_min_raw)
        elif ext_sec_raw.isdigit():
            arr_min = max(1, round(int(ext_sec_raw) / 60))

        prev_stops = int(status_pos) if status_pos.isdigit() else None
        if arr_min is not None or msg_tp in ("01", "02", "03", "04", "06"):
            results.append(
                {
                    "route_no": r_no,
                    "arr_min": 0 if msg_tp == "01" else (arr_min if arr_min is not None else 1),
                    "prev_cnt": prev_stops,
                    "msg_tp": msg_tp,
                    "is_last": last_cat == "1",
                    "dest": dest_nm,
                }
            )
    results.sort(key=lambda x: x["arr_min"])
    return {"ok": True, "items": results}


