def get_kst_now() -> datetime:
    return datetime.now(ZoneInfo("Asia/Seoul"))


def parse_hhmm_to_min(hhmm: str) -> int:
    h, m = hhmm.strip().split(":")
    return int(h) * 60 + int(m)


def min_to_hhmm(total_min: int) -> str:
    m = total_min % (24 * 60)
    return f"{m // 60:02d}:{m % 60:02d}"


def format_remain_str(diff_min: int) -> str:
    if diff_min <= 0:
        return "곧 도착"
    if diff_min < 60:
        return f"약 {diff_min}분 후"
    h, m = divmod(diff_min, 60)
    return f"{h}시간 {m}분 남음" if m else f"{h}시간 남음"


def estimate_segment_min(u: str, v: str) -> int:
    if u == v:
        return 0
    nu, nv = NODES.get(u), NODES.get(v)
    if not nu or not nv:
        return 4
    dist = math.hypot(nu["x"] - nv["x"], nu["y"] - nv["y"])
    return int(max(2, min(7, round(dist * 0.38))))


def get_sorted_stops() -> list[str]:
    hubs = [h for h in MAJOR_HUBS if h in NODES]
    others = sorted(s for s in NODES if s not in hubs)
    return hubs + others


def get_reachable_stops(origin: str) -> set[str]:
    reach = set()
    for info in BUS_ROUTES.values():
        stops = info["stops"]
        if origin in stops:
            for s in stops:
                if s != origin:
                    reach.add(s)
    return reach


def format_stop_option(stop_name: str, direct_set: set[str] | None = None) -> str:
    reg = NODES[stop_name]["region"]
    prefix = "⭐ " if NODES[stop_name]["hub"] else ""
    if direct_set is not None:
        tag = " · 직통" if stop_name in direct_set else " · 환승"
        return f"{prefix}{stop_name} ({reg}{tag})"
    return f"{prefix}{stop_name} ({reg})"


def _clean_stop_token(s: str) -> str:
    return re.sub(r"[\s\(\)·\-]", "", s or "")


def match_geumsan_live_bus(
    service_key: str,
    bus_no: str,
    active_stops: list[str],
    origin: str,
) -> dict:
    """
    금산군(34310) 해당 노선의 실시간 운행 차량 조회 후,
    내 승차 정류장(origin) 이전에 접근 중인 차량이 있는지 계산
    """
    if not service_key:
        return {"api_checked": False, "ok": False, "buses": [], "approaching": None, "msg": "API 키 미설정"}

    route_ids = GEUMSAN_TAGO_ROUTES.get(bus_no, [])
    if not route_ids:
        return {"api_checked": False, "ok": False, "buses": [], "approaching": None, "msg": "TAGO 노선코드 없음"}

    all_buses = []
    any_ok = False
    last_msg = ""
    for rid in route_ids:
        res = fetch_tago_bus_locations(service_key, 34310, rid)
        if res["ok"]:
            any_ok = True
            for b in res["buses"]:
                b_copy = dict(b)
                b_copy["route_id"] = rid
                all_buses.append(b_copy)
        else:
            last_msg = res["msg"]

    if not any_ok:
        return {"api_checked": True, "ok": False, "buses": [], "approaching": None, "msg": last_msg}

    if not all_buses:
        return {"api_checked": True, "ok": True, "buses": [], "approaching": None, "msg": "현재 도로 위 운행 중인 차량 없음"}

    # 내 정류장(origin) 위치와 실시간 버스 정류장 이름 매칭
    o_idx = active_stops.index(origin) if origin in active_stops else 0
    approaching_candidates = []
    for b in all_buses:
        cur_nm = _clean_stop_token(b["node_nm"])
        matched_idx = None
        for i, st_nm in enumerate(active_stops):
            tok = _clean_stop_token(st_nm)
            if tok and (tok in cur_nm or cur_nm in tok):
                matched_idx = i
                break
        b["matched_idx"] = matched_idx
        if matched_idx is not None and matched_idx <= o_idx:
            rem_major_stops = o_idx - matched_idx
            est_min = sum(
                estimate_segment_min(active_stops[k], active_stops[k + 1])
                for k in range(matched_idx, o_idx)
            )
            b["rem_major_stops"] = rem_major_stops
            b["est_live_min"] = max(1, est_min) if rem_major_stops > 0 else 0
            approaching_candidates.append(b)

    approaching = None
    if approaching_candidates:
        approaching_candidates.sort(key=lambda x: x["est_live_min"])
        approaching = approaching_candidates[0]

    return {
        "api_checked": True,
        "ok": True,
        "buses": all_buses,
        "approaching": approaching,
        "msg": f"현재 노선 위 {len(all_buses)}대 운행 중",
    }


def evaluate_geumsan_route(bus_no: str, origin: str, dest: str, now_min: int) -> dict | None:
    info = BUS_ROUTES[bus_no]
    stops = info["stops"]
    if origin not in stops or dest not in stops or origin == dest:
        return None

    idx_o = stops.index(origin)
    idx_d = stops.index(dest)

    if idx_o < idx_d:
        active_stops = stops
        raw_times = info["out_times"]
    else:
        active_stops = list(reversed(stops))
        raw_times = info["in_times"] if info["in_times"] else info["out_times"]

    o_pos = active_stops.index(origin)
    d_pos = active_stops.index(dest)
    start_terminal = active_stops[0]
    end_terminal = active_stops[-1]

    offset_to_origin = sum(
        estimate_segment_min(active_stops[i], active_stops[i + 1]) for i in range(o_pos)
    )
    ride_min = sum(
        estimate_segment_min(active_stops[i], active_stops[i + 1]) for i in range(o_pos, d_pos)
    )

    sched_entries = sorted(
        [(parse_hhmm_to_min(t), t) for t in raw_times],
        key=lambda x: x[0],
    )
    if not sched_entries:
        return None

    upcoming = []
    for dep_m, dep_str in sched_entries:
        est_board_m = dep_m + offset_to_origin
        if est_board_m >= now_min:
            upcoming.append((dep_m, dep_str, est_board_m))

    first_dep_m, first_dep_str = sched_entries[0]
    if upcoming:
        next_dep_m, next_dep_str, next_board_m = upcoming[0]
        wait_from_now = next_board_m - now_min
        rem_count = len(upcoming)
        is_ended = False
        if rem_count == 1:
            lb_level, lb_badge = "last", "🚨 오늘 마지막 차(막차)"
        elif rem_count == 2:
            lb_level, lb_badge = "warn", "⏰ 막차 1대 전"
        else:
            lb_level, lb_badge = "ok", f"오늘 {rem_count}회 남음"
    else:
        next_dep_m = first_dep_m
        next_dep_str = first_dep_str
        next_board_m = first_dep_m + offset_to_origin
        wait_from_now = (24 * 60 - now_min) + next_board_m
        rem_count = 0
        is_ended = True
        lb_level, lb_badge = "ended", f"🌙 오늘 운행 종료 (첫차 {first_dep_str})"

    return {
        "bus_no": bus_no,
        "name": info["name"],
        "category": info["category"],
        "region": info["region"],
        "desc": info["desc"],
        "start_terminal": start_terminal,
        "end_terminal": end_terminal,
        "active_stops": active_stops,
        "offset_to_origin": offset_to_origin,
        "ride_min": ride_min,
        "all_dep_times": [s for _, s in sched_entries],
        "next_dep_m": next_dep_m,
        "next_dep_str": next_dep_str,
        "next_board_m": next_board_m,
        "next_board_str": min_to_hhmm(next_board_m),
        "est_alight_str": min_to_hhmm(next_board_m + ride_min),
        "wait_from_now": wait_from_now,
        "rem_count": rem_count,
        "is_ended": is_ended,
        "lb_level": lb_level,
        "lb_badge": lb_badge,
    }


def find_all_geumsan_options(origin: str, dest: str, now_min: int, service_key: str) -> list[dict]:
    results = []
    for bno in BUS_ROUTES:
        ev = evaluate_geumsan_route(bno, origin, dest, now_min)
        if ev is not None:
            results.append(ev)

    results.sort(key=lambda x: (1 if x["is_ended"] else 0, x["wait_from_now"], x["ride_min"]))

    # 상위 5개 후보 노선에 대해 실시간 GPS 차량 위치 조회 결합
    for opt in results[:5]:
        opt["live"] = match_geumsan_live_bus(
            service_key=service_key,
            bus_no=opt["bus_no"],
            active_stops=opt["active_stops"],
            origin=origin,
        )
    for opt in results[5:]:
        opt["live"] = {"api_checked": False, "ok": False, "buses": [], "approaching": None, "msg": ""}

    # 실시간 접근 중인 버스가 있으면 최우선 정렬!
    def _sort_key(item: dict):
        appr = item["live"].get("approaching")
        if appr is not None:
            return (0, appr["est_live_min"], item["ride_min"])
        return (1, 1 if item["is_ended"] else 0, item["wait_from_now"], item["ride_min"])

    results.sort(key=_sort_key)
    return results


def find_simple_transfer(origin: str, dest: str, now_min: int) -> dict | None:
    best = None
    for hub in MAJOR_HUBS:
        if hub in (origin, dest) or hub not in NODES:
            continue
        leg1_list = find_all_geumsan_options(origin, hub, now_min, "")
        leg2_list = find_all_geumsan_options(hub, dest, now_min, "")
        if leg1_list and leg2_list:
            l1, l2 = leg1_list[0], leg2_list[0]
            score = l1["wait_from_now"] + l1["ride_min"] + l2["ride_min"]
            if best is None or score < best["score"]:
                best = {"hub": hub, "leg1": l1, "leg2": l2, "score": score}
    return best


def evaluate_daejeon_34(
    direction_key: str,
    origin_name: str,
    dest_name: str,
    now_min: int,
    service_key: str,
) -> dict:
    """대전 외곽버스 34번 실시간 GPS 위치 + 정류소 전광판 + 공식 기점 시간표 통합 계산"""
    to_daedun = direction_key == "to_daedun"
    stops = DAEJEON_34_STOPS_TO_DAEDUN if to_daedun else DAEJEON_34_STOPS_TO_DAEJEON
    col_key = "seonambu" if to_daedun else "daedunsan"
    start_terminal = "서남부터미널기점" if to_daedun else "대둔산휴게소"
    dir_title = "대전 서남부터미널 ➔ 복수 · 진산 · 대둔산" if to_daedun else "대둔산 · 진산 · 복수 ➔ 대전 서남부터미널"

    names = [s["name"] for s in stops]
    idx_o = names.index(origin_name) if origin_name in names else 0
    idx_d = names.index(dest_name) if dest_name in names else len(stops) - 1
    if idx_d <= idx_o:
        idx_d = min(len(stops) - 1, idx_o + 1)

    o_item = stops[idx_o]
    d_item = stops[idx_d]
    offset_o = o_item["min"]
    ride_min = max(2, d_item["min"] - o_item["min"])

    dep_times = [row[col_key] for row in DAEJEON_34_TIMETABLE]
    sched_entries = [(parse_hhmm_to_min(t), t) for t in dep_times]

    upcoming = []
    for dep_m, dep_str in sched_entries:
        est_board_m = dep_m + offset_o
        if est_board_m >= now_min:
            upcoming.append((dep_m, dep_str, est_board_m))

    first_dep_m, first_dep_str = sched_entries[0]
    if upcoming:
        next_dep_m, next_dep_str, next_board_m = upcoming[0]
        wait_from_now = next_board_m - now_min
        rem_count = len(upcoming)
        is_ended = False
        if rem_count == 1:
            lb_level, lb_badge = "last", "🚨 오늘 마지막 34번(막차)"
        elif rem_count == 2:
            lb_level, lb_badge = "warn", "⏰ 막차 1대 전"
        else:
            lb_level, lb_badge = "ok", f"오늘 {rem_count}회 남음"
    else:
        next_dep_m = first_dep_m
        next_dep_str = first_dep_str
        next_board_m = first_dep_m + offset_o
        wait_from_now = (24 * 60 - now_min) + next_board_m
        rem_count = 0
        is_ended = True
        lb_level, lb_badge = "ended", f"🌙 오늘 운행 종료 (첫차 {first_dep_str})"

    # 실시간 조회 (1순위: 대전 정류소 도착정보 / TAGO 정류소 도착정보 -> 2순위: TAGO 버스위치정보 nodeOrd 계산)
    live_info = {
        "api_checked": bool(service_key),
        "ok": False,
        "source": "",
        "live_eta_min": None,
        "prev_stops": None,
        "current_stop_nm": "",
        "vehicle_no": "",
        "all_dir_buses": [],
        "all_route_buses": [],
        "msg": "API 키 미설정",
    }

    if service_key:
        # A. 정류소 도착예정 API 시도 (대전 BIS / TAGO Arvl)
        dj_ars = fetch_daejeon_ars_arrival(service_key, o_item.get("id", ""), "34")
        tago_arr = fetch_tago_stop_arrival(service_key, 25, o_item.get("node_id", ""), DAEJEON_34_ROUTE_ID)

        # B. TAGO 실시간 차량 위치 API (현재 키로 즉시 작동 확인 완료!)
        lc_res = fetch_tago_bus_locations(service_key, 25, DAEJEON_34_ROUTE_ID)
        live_info["ok"] = lc_res["ok"] or dj_ars["ok"] or tago_arr["ok"]
        live_info["msg"] = lc_res["msg"]

        ord_min_bound = 1 if to_daedun else 48
        ord_max_bound = 47 if to_daedun else 90
        target_ord = o_item["node_ord"]

        # ord -> 소요분 보간용 딕셔너리
        ord_to_min_map = {s["node_ord"]: s["min"] for s in stops}

        def _interp_min_by_ord(ord_val: int) -> int:
            if ord_val in ord_to_min_map:
                return ord_to_min_map[ord_val]
            nearest = min(stops, key=lambda x: abs(x["node_ord"] - ord_val))
            diff_ord = ord_val - nearest["node_ord"]
            return max(0, nearest["min"] + round(diff_ord * 1.3))

        if lc_res["ok"]:
            live_info["all_route_buses"] = lc_res["buses"]
            dir_buses = [
                b for b in lc_res["buses"]
                if ord_min_bound <= b["node_ord"] <= ord_max_bound
            ]
            live_info["all_dir_buses"] = dir_buses

            # 내 정류장(target_ord) 이전에 오고 있는 버스 중 가장 가까운 차량 선택
            approaching = [b for b in dir_buses if b["node_ord"] <= target_ord]
            if approaching:
                nearest_bus = max(approaching, key=lambda b: b["node_ord"])
                prev_cnt = target_ord - nearest_bus["node_ord"]
                bus_min_pos = _interp_min_by_ord(nearest_bus["node_ord"])
                eta_m = max(1, offset_o - bus_min_pos) if prev_cnt > 0 else 0
                live_info.update(
                    {
                        "source": "국토부 TAGO 실시간 GPS 위치",
                        "live_eta_min": eta_m,
                        "prev_stops": prev_cnt,
                        "current_stop_nm": nearest_bus["node_nm"],
                        "vehicle_no": nearest_bus["vehicle_no"],
                    }
                )

        # 정류소 전광판 API에서 직접 초/분 단위 도착시간이 왔다면 보강
        if dj_ars["ok"] and dj_ars["items"]:
            top_a = dj_ars["items"][0]
            live_info["source"] = "대전시 실시간 정류소 전광판"
            live_info["live_eta_min"] = top_a["arr_min"]
            if top_a["prev_cnt"] is not None:
                live_info["prev_stops"] = top_a["prev_cnt"]
        elif tago_arr["ok"] and tago_arr["items"]:
            top_t = tago_arr["items"][0]
            live_info["source"] = "국토부 실시간 도착정보 전광판"
            live_info["live_eta_min"] = top_t["arr_min"]
            live_info["prev_stops"] = top_t["prev_cnt"]

    return {
        "dir_title": dir_title,
        "start_terminal": start_terminal,
        "stops": stops,
        "origin_item": o_item,
        "dest_item": d_item,
        "offset_o": offset_o,
        "ride_min": ride_min,
        "dep_times": dep_times,
        "next_dep_str": next_dep_str,
        "next_board_str": min_to_hhmm(next_board_m),
        "est_alight_str": min_to_hhmm(next_board_m + ride_min),
        "wait_from_now": wait_from_now,
        "rem_count": rem_count,
        "is_ended": is_ended,
        "lb_level": lb_level,
        "lb_badge": lb_badge,
        "live": live_info,
    }


def _embed_html(html_code: str, height: int) -> None:
    if hasattr(st, "iframe"):
        st.iframe(html_code, height=height)
    else:
        components.html(html_code, height=height, scrolling=False)


def render_bus_gps_map(buses, *, key_ready, label):
    st.markdown(f"#### 🗺️ {label} 버스 위치")
    points = []
    for bus in buses:
        try:
            lat, lon = float(bus.get("lat")), float(bus.get("lon"))
        except (ValueError, TypeError, OverflowError):
            continue
        if math.isfinite(lat) and math.isfinite(lon) and 33 <= lat <= 39 and 124 <= lon <= 132:
            points.append((lat, lon))
    if not points:
        st.caption("현재 표시할 GPS 좌표가 없어요. 아래 시간표를 확인해 주세요." if key_ready else "실시간 위치를 보려면 공공데이터 API 키를 설정해 주세요.")
        return
    st.caption("점 하나는 API에서 위치를 받아온 차량을 뜻해요. 다시 조회하려면 위의 새로고침을 눌러 주세요.")
    st.map(pd.DataFrame(points, columns=["lat", "lon"]), latitude="lat", longitude="lon", size=90)


def render_tts_button(tts_text: str) -> None:
    """어르신용 한국어 음성 안내 버튼"""
    safe_json = json.dumps(tts_text, ensure_ascii=False)
    code = f"""<!DOCTYPE html>
<html lang="ko"><head><meta charset="utf-8">
<style>
  * {{ box-sizing: border-box; font-family: 'Pretendard', 'Malgun Gothic', sans-serif; }}
  body {{ margin: 0; padding: 0; background: transparent; }}
  .wrap {{ display: flex; gap: 8px; align-items: center; }}
  .btn-play {{
    flex: 1; background: #1D4ED8; color: #fff; border: none; border-radius: 12px;
    padding: 12px 16px; font-size: 1rem; font-weight: 800; cursor: pointer;
  }}
  .btn-stop {{
    background: #F1F5F9; color: #334155; border: 1.5px solid #CBD5E1; border-radius: 12px;
    padding: 12px 14px; font-size: 0.95rem; font-weight: 700; cursor: pointer;
  }}
</style></head>
<body>
  <div class="wrap">
    <button class="btn-play" id="playBtn" onclick="speakBus()">🔊 소리로 안내 듣기</button>
    <button class="btn-stop" onclick="stopBus()">⏹️ 멈춤</button>
  </div>
  <script>
    const msgText = {safe_json};
    function speakBus() {{
      if (!('speechSynthesis' in window)) {{
        alert('이 브라우저에서는 음성 안내를 지원하지 않습니다.');
        return;
      }}
      window.speechSynthesis.cancel();
      const u = new SpeechSynthesisUtterance(msgText);
      u.lang = 'ko-KR';
      u.rate = 0.92;
      const btn = document.getElementById('playBtn');
      u.onstart = () => {{ btn.innerText = '🔊 안내 읽는 중...'; }};
      u.onend = () => {{ btn.innerText = '🔊 소리로 안내 듣기'; }};
      u.onerror = () => {{ btn.innerText = '🔊 소리로 안내 듣기'; }};
      window.speechSynthesis.speak(u);
    }}
    function stopBus() {{
      if ('speechSynthesis' in window) window.speechSynthesis.cancel();
      document.getElementById('playBtn').innerText = '🔊 소리로 안내 듣기';
    }}
  </script>
</body></html>"""
    _embed_html(code, height=54)


def render_time_badges(times: list[str], offset_min: int, now_min: int, accent_green: bool = False) -> str:
    chips = []
    marked_next = False
    for idx, t_str in enumerate(times):
        dep_m = parse_hhmm_to_min(t_str)
        board_m = dep_m + offset_min
        is_last = idx == len(times) - 1
        if board_m >= now_min and not marked_next:
            marked_next = True
            cls = "t-next-green" if accent_green else "t-next-blue"
            suffix = " · 막차" if is_last else " · 다음차"
            chips.append(f"<span class='t-chip {cls}'>🚌 {t_str}{suffix}</span>")
        elif board_m < now_min:
            chips.append(f"<span class='t-chip t-past'>{t_str}</span>")
        elif is_last:
            chips.append(f"<span class='t-chip t-last'>{t_str} (막차)</span>")
        else:
            chips.append(f"<span class='t-chip t-future'>{t_str}</span>")
    return "".join(chips)


